import pandas as pd
import json

def read_file(filepath):
    if filepath.endswith('.csv'):
        return pd.read_csv(filepath)
    elif filepath.endswith('.txt'):
        # Assuming tab or space separated, but pandas can often guess. 
        # Given the preview looks like a standard delimited file, we try sep=None with engine='python' for robustness
        return pd.read_csv(filepath, sep=None, engine='python')
    else:
        raise ValueError("Unsupported file format")

# Read data
df_a = read_file("/home/chs/Work/tga_plot/eval/inputs_b/cnt_lot_A.csv")
df_b = read_file("/home/chs/Work/tga_plot/eval/inputs_b/cnt_lot_B.txt")

# Extract columns based on preview info
# X: Temperature (°C), Y1: Weight (%), Y2: Deriv. Weight (%/°C)
x_col = 'Temperature (°C)'
y1_col = 'Weight (%)'
y2_col = 'Deriv. Weight (%/°C)'

# Prepare data for ECharts
# We need to handle NaN values properly if any, though preview suggests clean data.
# Convert to lists of [x, y] pairs for scatter/line series

data_a_weight = [[row[x_col], row[y1_col]] for _, row in df_a.iterrows() if pd.notna(row[x_col]) and pd.notna(row[y1_col])]
data_a_deriv = [[row[x_col], row[y2_col]] for _, row in df_a.iterrows() if pd.notna(row[x_col]) and pd.notna(row[y2_col])]

data_b_weight = [[row[x_col], row[y1_col]] for _, row in df_b.iterrows() if pd.notna(row[x_col]) and pd.notna(row[y1_col])]
data_b_deriv = [[row[x_col], row[y2_col]] for _, row in df_b.iterrows() if pd.notna(row[x_col]) and pd.notna(row[y2_col])]

